using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using SchoolERP.Api.Security;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Features.ClassSections;using SchoolERP.Domain.Security;using SchoolERP.Shared.Models;
namespace SchoolERP.Api.Controllers.v1;[ApiController,Authorize,Route("api/v1/classes/{classId:guid}/sections")]public sealed class ClassSectionHierarchyController(IClassSectionService s):ControllerBase{[HttpGet,RequirePermission(PermissionCatalog.Section.View)]public async Task<ActionResult<ApiResponse<PagedResult<ClassSectionListItemDto>>>>List(Guid classId,[FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,CancellationToken ct=default)=>Ok(ApiResponse<PagedResult<ClassSectionListItemDto>>.Ok(await s.ListForClassAsync(classId,new(pageNumber,pageSize),ct)));[HttpPost,RequirePermission(PermissionCatalog.Section.Create)]public async Task<ActionResult<ApiResponse<ClassSectionDetailsDto>>>Create(Guid classId,CreateClassSectionRequest r,CancellationToken ct){var x=await s.CreateAsync(classId,r,ct);return Created($"/api/v1/sections/{x.Id}",ApiResponse<ClassSectionDetailsDto>.Ok(x));}}
